package main

import "fmt"

func main() {
    // Example of a simple regex match
    command := "ps aux"
    regex := "ps.*"

    match, err := regexp.MatchString(regex, command)
    if err != nil {
        fmt.Println("Error:", err)
    } else {
        fmt.Println("Match found:", match)
    }
